import{_ as a,a0 as e,w as i,s as p,ao as s,I as l,x as n,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"Ubuntu After Install – 帮你在Ubuntu上自动安装流行的软件 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu After Install – 帮你在Ubuntu上自动安装流行的软件 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu After Install – 帮你在Ubuntu上自动安装流行的软件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu After Install – 帮你在Ubuntu上自动安装流行的软件 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Ubuntu After Install--Automate the Installation of all popular softwares On Ubuntu 14.04 or 13.10 or 13.04 or 12.10 or 12.04","title":"Ubuntu After Install – 帮你在Ubuntu上自动安装流行的软件","tag":"201405","desc":""},"relativePath":"201405/Ubuntu After Install--Automate the Installation of all popular softwares On Ubuntu 14.04 or 13.10 or 13.04 or 12.10 or 12.04.md","filePath":"[post].md"}'),b={name:"201405/Ubuntu After Install--Automate the Installation of all popular softwares On Ubuntu 14.04 or 13.10 or 13.04 or 12.10 or 12.04.md"};function g(f,t,d,U,m,A){const u=e("Link");return i(),p("div",null,[t[22]||(t[22]=s(`<h1 id="ubuntu-after-install-–-帮你在ubuntu上自动安装流行的软件" tabindex="-1">Ubuntu After Install – 帮你在Ubuntu上自动安装流行的软件 <a class="header-anchor" href="#ubuntu-after-install-–-帮你在ubuntu上自动安装流行的软件" aria-label="Permalink to “Ubuntu After Install – 帮你在Ubuntu上自动安装流行的软件”">​</a></h1><p>在你刚刚更新或者是安装了一个新的Ubuntu桌面版之后，你是不是想安装一些有用的并且必要的软件呢？当然。但是，为了打造一个完美的Ubuntu系统，你会需要付出很大的努力。你还会吗？你会怎么去做？你真的会去手动通过添加软件源或者是下载<strong>.deb</strong>包去寻找和安装每一个软件？或者不分青红皂白安装所有的软件？我觉得这将是一个漫长的过程，并且你们也不知道你们需要什么软件去打造这么一个完美的Ubuntu桌面。</p><p>好的，如果有一个简单的工具能让你达到上面的目的，且只需要你点击两下鼠标，你会怎么做？这真会有一个简单的并且有趣的工具，帮助我们安装所有的必须和流行的软件，并且只需要双击鼠标？是的，还真有。为了满足你的好奇心，我可以很负责任的告诉你，这就是<strong>Ubuntu After Install</strong>。</p><p><strong>Ubuntu After Install</strong>是用来在安装Ubuntu桌面之后安装一些最好的和必要的软件的工具。还有，它还包含了许多有用的应用程序，并且可以自动执行安装过程新安装的机器，让它接近完美的桌面。我不敢说它可以提供给所有用户一个完美的桌面，但一个近乎完美的桌面绝对是可以的。这个工具不仅可以节省您的时间和精力，而且会自动添加相应的PPA来自动更新，让你始终使用着最新的软件。</p><p><strong>Ubuntu After Install</strong>会安装的软件的完整名单如下：</p><ul><li><strong>Ubuntu Restricted Extras</strong>: 视频解码和Flash支持</li><li><strong>libdvdcss</strong> DVD重放</li><li><strong>Unity Tweak Tool</strong> 优化你的Ubuntu桌面</li><li><strong>Variety</strong> Ubuntu桌面壁纸切换</li><li><strong>Google Chrome</strong> 可能是世界上最好的浏览器</li><li><strong>LibreOffice</strong> 完全开源的办公软件</li><li><strong>Skype</strong> 提供文字，声音，视频聊天</li><li><strong>Grive Tools</strong> 同步你的Google Driver</li><li><strong>DropBox</strong> 同步你的DropBox存储</li><li><strong>VLC</strong> 能播放你能想象的视频文件</li><li><strong>XBMC</strong> 一个媒体中心软件</li><li><strong>Radio Tray</strong> 一款不错的基于面板的广播系统</li><li><strong>GIMP</strong> 强大的图片编辑软件</li><li><strong>Darktable</strong> 允许摄影师编辑RAW文件</li><li><strong>Inkscape</strong> 开源矢量图形编辑软件</li><li><strong>Scribus</strong> 专业的桌面发布软件</li><li><strong>Samba</strong> 允许Windows网络共享</li><li><strong>PDF Tools</strong> 合并、剪切、添加、修改PDF文档工具</li><li><strong>OpenShot</strong> 流行的视频编辑软件</li><li><strong>Kdenlive</strong> 更加先进的视频编辑软件</li><li><strong>Handbrake</strong> 将视频和DVD转换为移动端可播放格式</li><li><strong>Audacity</strong> 声音，音乐编辑工具</li><li><strong>Steam</strong> Linuxu游戏平台</li><li><strong>KeePass</strong> 安全的储存你的密码</li><li><strong>Shutter</strong> 让你很容易的截屏</li><li><strong>FileZilla</strong> FTP工具</li><li><strong>p7zip</strong> 强大的7zip压缩/解压工具</li><li>还有一些即将到来的新特性</li></ul><h3 id="在ubuntu-12-04或者更新一些的系统上-安装-ubuntu-after-install" tabindex="-1">在Ubuntu 12.04或者更新一些的系统上 安装‘Ubuntu After Install’ <a class="header-anchor" href="#在ubuntu-12-04或者更新一些的系统上-安装-ubuntu-after-install" aria-label="Permalink to “在Ubuntu 12.04或者更新一些的系统上 安装‘Ubuntu After Install’”">​</a></h3><p>添加‘Ubuntu After Install’ PPA 并且执行以下命令</p><pre><code>sudo add-apt-repository ppa:thefanclub/ubuntu-after-install
sudo apt-get update
sudo apt-get install ubuntu-after-install
</code></pre>`,9)),l("p",null,[t[1]||(t[1]=n("你也可以从",-1)),r(u,{href:"http://www.thefanclub.co.za/sites/all/modules/pubdlcnt/pubdlcnt.php?file=http://www.thefanclub.co.za/sites/default/files/public/downloads/ubuntu-after-install_2.4_all.deb&nid=121"},{default:o(()=>[...t[0]||(t[0]=[n("这里",-1)])]),_:1}),t[2]||(t[2]=n("手动下载 .deb 文件，并且手动安装。",-1))]),t[23]||(t[23]=s('<h3 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to “使用说明”">​</a></h3><p>安装完Ubuntu-After-Install之后，你只需要从Dash或者菜单里启动他即可。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/Menu_001.png" alt=""></p><p>这就是Ubuntu-after-install的外观。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/Ubuntu-After-Install-2.4-beta_002.png" alt=""></p><p>正如你在上面的截图中看到，它会显示所有有用的软件。已经被安装了软件会标有绿色的色点，且默认不会选中。如果某一款软件不适用于您的Ubuntu版本，那么它将被标记为红色圆点。还有，标志着橙色的软件则是需要重新安装和更新的。清楚了吗？</p><p>现在，选择您想要安装并按下按钮<strong>立即安装</strong>。所选软件的PPA将会自动添加到系统中，并且也会在系统上自动安装。听起来不错，不是吗？</p><p>例如，在这里我只想安装在我的Ubuntu14.04系统上安装p7zip。所以我只选择了p7zip的包，并取消其他的程序。只需要轻轻点击<strong>立即安装</strong>按钮，就可以开始安装。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/Ubuntu-After-Install-2.4-beta_003.png" alt=""></p><p>现在，安装程序会在你电脑上自动添加p7zip的PPA并且安装它。而且一切都将自动在后台完成。所以，你什么都不需要做。只需要，要放松心情，喝杯咖啡，观看安装。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/Ubuntu-After-Install-2.4-beta_004.png" alt=""></p><p>如果软件已经安装成功，它将被标记为绿色的色点。请记住，一次安装所有的应用程序将需要一段时间取决于您的Internet连接速度来完成的，这是安装过程一旦开始，强行取消是非常不可取的。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3>',13)),l("p",null,[t[4]||(t[4]=n("在之前，我们刚刚提到了",-1)),r(u,{href:"http://www.unixmen.com/after-a-fresh-install-of-ubuntu-1010-maverick-meerkat-configuration-made-easy-with-ubuntu-tweak/"},{default:o(()=>[...t[3]||(t[3]=[n("Ubuntu Tweak",-1)])]),_:1}),t[5]||(t[5]=n("。 ",-1)),t[6]||(t[6]=l("strong",null,"Ubuntu Tweak",-1)),t[7]||(t[7]=n("和",-1)),t[8]||(t[8]=l("strong",null,"Ubuntu After Install",-1)),t[9]||(t[9]=n("是类似的工具, 但是Ubuntu Tweak有着比Ubuntu After Install更多的特点。 Ubuntu After Tool只是为了帮你安装了所有最好的和日常使用的软件, 而Ubuntu的调整工具会做对额外的东西，如定制您的Ubuntu桌面和更多。",-1))]),t[24]||(t[24]=l("p",null,"不要再在网络上寻找所谓的Ubuntu必备软件上浪费你的宝贵的时间。Ubuntu Tweak和Ubuntu After Install就是为了帮助那些正在寻找Ubuntu必备软件的人准备的。所以，不要再犹豫，马上使用它们！",-1)),t[25]||(t[25]=l("p",null,"希望能帮助到你，就说这么多了。",-1)),t[26]||(t[26]=l("p",null,"祝你好运!",-1)),t[27]||(t[27]=l("p",null,"来源与参考:",-1)),l("ul",null,[l("li",null,[r(u,{href:"http://www.thefanclub.co.za/how-to/ubuntu-after-install"},{default:o(()=>[...t[10]||(t[10]=[n("The Fan Club Website",-1)])]),_:1})])]),t[28]||(t[28]=l("hr",null,null,-1)),l("p",null,[t[12]||(t[12]=n("via: ",-1)),r(u,{href:"http://www.unixmen.com/ubuntu-install-automate-installation-popular-softwares-ubuntu-14-0413-1013-0412-1012-04/"},{default:o(()=>[...t[11]||(t[11]=[n("http://www.unixmen.com/ubuntu-install-automate-installation-popular-softwares-ubuntu-14-0413-1013-0412-1012-04/",-1)])]),_:1})]),l("p",null,[t[15]||(t[15]=n("译者：",-1)),r(u,{href:"https://github.com/MikeCoder"},{default:o(()=>[...t[13]||(t[13]=[n("MikeCoder",-1)])]),_:1}),t[16]||(t[16]=n(" 校对：",-1)),r(u,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:o(()=>[...t[14]||(t[14]=[n("校对者ID",-1)])]),_:1})]),l("p",null,[t[19]||(t[19]=n("本文由 ",-1)),r(u,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[17]||(t[17]=[n("LCTT",-1)])]),_:1}),t[20]||(t[20]=n(" 原创翻译，",-1)),r(u,{href:"http://linux.cn/"},{default:o(()=>[...t[18]||(t[18]=[n("Linux中国",-1)])]),_:1}),t[21]||(t[21]=n(" 荣誉推出",-1))])])}const C=a(b,[["render",g]]);export{I as __pageData,C as default};
